// CLM for Claude Code: the model manages its own context by editing a mirror file.
// A port of pi-clm (https://github.com/lolipopshock/pi-clm, MIT) for the paper
// "Context Language Models" (arXiv 2609.37725).
//
// Claude Code pins the messages of each model request, so an accepted edit is
// installed between turns through the compaction path: a `session.compact` hook
// answers with the edited conversation instead of a summary.

import type { EngineInterface, Register, SessionMessage } from 'claude-code'

import { apply, applyOps, digest, estimateTokens, listBlocks, parse, render, withhold, type Op, type Snapshot } from './document'
import { APPLY_TAG, budgetNote, compactPrompt, EDIT_TOOL, EDIT_TOOL_DESCRIPTION, EDIT_TOOL_SCHEMA, formatCount, parseReminders, protocol } from './text'

type History = {
  revision: number
  at: string
  kind: 'edit' | 'guard'
  kept: number
  edited: number
  added: number
  removed: number
  tokensBefore: number
  tokensAfter: number
}

type State = {
  enabled: boolean
  revision: number
  nonce: string
  snapshot?: Snapshot
  isPending: boolean
  lastTier: number
  lastOutcome?: string
  history: History[]
}

type Options = { budget: number; reminders: string; guard: boolean; steering: string }

const FRESH: State = { enabled: true, revision: 0, nonce: '', isPending: false, lastTier: 0, history: [] }

let steeringText: string | undefined

function newNonce(): string {
  return Array.from({ length: 16 }, () => Math.floor(Math.random() * 16).toString(16)).join('')
}

async function dirOf($: EngineInterface): Promise<string> {
  const tmp = ((await $.env.get('TMPDIR')) ?? '/tmp').replace(/\/+$/, '')
  return `${tmp}/claude-clm/${await $.session.id()}`
}

async function mirrorOf($: EngineInterface): Promise<string> {
  return `${await dirOf($)}/LIVE_CONTEXT.md`
}

async function load($: EngineInterface): Promise<State> {
  try {
    return { ...FRESH, ...JSON.parse(await $.fs.read(`${await dirOf($)}/state.json`)) }
  } catch {
    return { ...FRESH, nonce: newNonce() }
  }
}

async function save($: EngineInterface, state: State): Promise<void> {
  await $.fs.write(`${await dirOf($)}/state.json`, JSON.stringify(state))
}

async function readMirror($: EngineInterface): Promise<string | undefined> {
  try {
    return await $.fs.read(await mirrorOf($))
  } catch {
    return undefined
  }
}

// Write the conversation to the mirror unless the model has an edit in it.
async function refresh($: EngineInterface, state: State): Promise<State> {
  const onDisk = await readMirror($)
  if (state.snapshot && onDisk !== undefined && digest(onDisk) !== state.snapshot.textDigest) return state
  const messages = await $.session.messages()
  const { snapshot, text } = render(messages, state.revision, state.nonce)
  if (onDisk !== text) await $.fs.write(await mirrorOf($), text)
  const next = { ...state, snapshot }
  await save($, next)
  return next
}

async function contextTokens($: EngineInterface): Promise<{ tokens: number; window: number }> {
  const { context } = await $.session.usage()
  return { tokens: context.tokens ?? 0, window: context.window }
}

async function note($: EngineInterface, text: string): Promise<void> {
  await $.session.append({ message: { type: 'user', content: [{ type: 'text', text }] } })
}

async function remind($: EngineInterface, state: State, options: Options): Promise<State> {
  const tiers = parseReminders(options.reminders)
  if (tiers.length === 0) return state
  const { tokens, window } = await contextTokens($)
  const budget = options.budget > 0 ? options.budget : window
  if (!tokens || !budget) return state
  const pct = (tokens / budget) * 100
  const tier = [...tiers].reverse().find(t => pct >= t) ?? 0
  if (tier === state.lastTier) return state
  const next = { ...state, lastTier: tier }
  if (tier > state.lastTier) await note($, budgetNote(tokens, budget, tier, await mirrorOf($)))
  await save($, next)
  return next
}

// At turn end: is there an edit, and does it validate?
async function settle($: EngineInterface, state: State): Promise<State> {
  const text = await readMirror($)
  if (!state.snapshot || text === undefined || digest(text) === state.snapshot.textDigest) return state
  const parsed = parse(text, state.snapshot)
  if (!parsed.ok) {
    const outcome = `rejected: ${parsed.reason}`
    await note($, `[LIVE CONTEXT] Your mirror edit was rejected (${parsed.reason}). The mirror was rewritten from the current conversation; nothing changed.`)
    const next = { ...state, isPending: false, lastOutcome: outcome, snapshot: undefined }
    await save($, next)
    return refresh($, next)
  }
  const next = { ...state, isPending: true }
  await save($, next)
  return next
}

async function installNow($: EngineInterface): Promise<void> {
  try {
    await $.command.run({ command: 'compact', args: APPLY_TAG })
  } catch (error) {
    $.ui.log(`clm: the edit stays pending until the next /compact (${String(error)})`)
  }
}

async function applyEdit($: EngineInterface, state: State, messages: readonly SessionMessage[]) {
  const text = (await readMirror($)) ?? ''
  const parsed = state.snapshot ? parse(text, state.snapshot) : { ok: false as const, reason: 'no snapshot' }
  if (!parsed.ok || !state.snapshot) return { state: { ...state, isPending: false, lastOutcome: `rejected: ${parsed.ok ? '' : parsed.reason}` } }
  const mirror = await mirrorOf($)
  const isEditing = (u: SessionMessage['toolUses'][number]) =>
    u.tool === `mcp__clm__${EDIT_TOOL}` || (MIRROR_TOOLS.has(u.tool) && u.input.file_path === mirror)
  const result = apply(parsed.blocks, state.snapshot, messages, isEditing)
  const revision = state.revision + 1
  const tokensBefore = estimateTokens(result.charsBefore)
  const tokensAfter = estimateTokens(result.charsAfter)
  const summary = `revision ${revision} accepted: ${result.kept} kept, ${result.edited} edited, ${result.added} added, ${result.removed} removed; ~${formatCount(tokensBefore)} → ~${formatCount(tokensAfter)} tokens`
  const history: History = { revision, at: new Date().toISOString(), kind: 'edit', kept: result.kept, edited: result.edited, added: result.added, removed: result.removed, tokensBefore, tokensAfter }
  const next: State = { ...state, revision, nonce: newNonce(), snapshot: undefined, isPending: false, lastTier: 0, lastOutcome: summary, history: [...state.history, history] }
  const messagesOut = [...result.messages, { role: 'user' as const, text: `[LIVE CONTEXT] Your mirror ${summary}.`, toolUses: [] }]
  return { state: next, messages: messagesOut, tokensBefore, tokensAfter }
}

async function guard($: EngineInterface, state: State, messages: readonly SessionMessage[], options: Options) {
  const { window } = await contextTokens($)
  const budget = options.budget > 0 ? Math.min(options.budget, window) : window
  const dir = await dirOf($)
  const out = withhold(messages, budget * 4 * 0.5, dir)
  if (!out) return undefined
  for (const w of out.withheld) await $.fs.write(w.path, w.text)
  const before = estimateTokens(messages.reduce((n, m) => n + m.text.length + (m.toolResults ?? []).reduce((k, r) => k + r.text.length, 0), 0))
  const after = estimateTokens(out.charsAfter)
  const summary = `overflow guard withheld ${out.withheld.length} old tool result(s): ~${formatCount(before)} → ~${formatCount(after)} tokens; full text in ${dir}/withheld/`
  const history: History = { revision: state.revision + 1, at: new Date().toISOString(), kind: 'guard', kept: 0, edited: out.withheld.length, added: 0, removed: 0, tokensBefore: before, tokensAfter: after }
  const next: State = { ...state, revision: state.revision + 1, nonce: newNonce(), snapshot: undefined, lastTier: 0, lastOutcome: summary, history: [...state.history, history] }
  return { state: next, messages: [...out.messages, { role: 'user' as const, text: `[CLM BUDGET] ${summary}.`, toolUses: [] }] }
}

async function status($: EngineInterface, state: State, options: Options): Promise<string> {
  const { tokens, window } = await contextTokens($)
  const budget = options.budget > 0 ? options.budget : window
  const edits = state.history.filter(h => h.kind === 'edit').length
  const guards = state.history.length - edits
  return [
    `clm ${state.enabled ? 'on' : 'off'} · revision ${state.revision} · ${edits} edit(s), ${guards} guard run(s)${state.isPending ? ' · edit pending' : ''}`,
    `context ~${formatCount(tokens)} of ${formatCount(budget)} tokens`,
    `mirror ${await mirrorOf($)}`,
    state.lastOutcome ? `last: ${state.lastOutcome}` : 'last: no edit yet',
  ].join('\n')
}

async function steering($: EngineInterface, options: Options): Promise<string> {
  if (options.steering !== 'house') return ''
  steeringText ??= await $.fs.read(`${$.plugin.root}/steering/house-brief.md`)
  return `\n\n## Context-management guidance (house)\n\n${steeringText.trim()}`
}

async function isHeadless($: EngineInterface): Promise<boolean> {
  return (await $.session.surfaces()).length === 0
}

async function beforeStep($: EngineInterface, opts: Options): Promise<void> {
  const state = await load($)
  if (!state.enabled) return
  await remind($, await refresh($, state), opts)
}

async function afterTurn($: EngineInterface): Promise<void> {
  const state = await load($)
  if (!state.enabled) return
  const settled = await settle($, state)
  if (settled.isPending && !(await isHeadless($))) $.clock.after(0, () => void installNow($))
}

async function contextEdit($: EngineInterface, action: string, ops: readonly Op[]): Promise<string> {
  const state = await load($)
  if (!state.enabled) return 'clm is off.'
  const ready = state.snapshot ? state : await refresh($, state)
  const snapshot = ready.snapshot
  const text = await readMirror($)
  if (!snapshot || text === undefined) return 'The mirror is not ready yet; try again next turn.'
  if (action === 'list') return listBlocks(text, snapshot)
  if (ops.length === 0) return 'Nothing to apply: pass ops, or action "list" to see block ids.'
  const out = applyOps(text, snapshot, ops)
  if (!out.ok) return `Not applied: ${out.reason}`
  await $.fs.write(await mirrorOf($), out.text)
  const before = estimateTokens(text.length)
  const after = estimateTokens(out.text.length)
  return `Applied ${ops.length} operation(s) to the mirror: ~${formatCount(before)} → ~${formatCount(after)} tokens. It becomes your context when this turn ends.`
}

const MIRROR_TOOLS = new Set(['Read', 'Edit', 'Write', 'MultiEdit'])

export const register: Register = (on, options) => {
  const opts = options as unknown as Options

  on('session.start', async ($, e, next) => {
    await $.command.register({ name: 'clm', description: 'CLM status; /clm on, /clm off' })
    await $.command.register({ name: 'clm-compact', description: 'Ask Claude to compact its own context by editing the mirror' })
    await $.tool.register({ name: EDIT_TOOL, description: EDIT_TOOL_DESCRIPTION, inputSchema: EDIT_TOOL_SCHEMA })
    return next(e)
  })

  on('prompt.compose', async ($, e, next) => {
    const out = await next(e)
    const state = await load($)
    if (!state.enabled) return out
    const text = protocol(await mirrorOf($)) + (await steering($, opts))
    return { sections: [...out.sections, { id: 'clm:protocol', text, scope: 'session' as const }] }
  })

  on('turn.step', async function* ($, e, next) {
    // Rendered once per turn: re-rendering mid-turn would invalidate the model's
    // read of the file before its edit lands.
    if (e.agentId === undefined && e.index === 0) await beforeStep($, opts).catch(error => $.ui.log(`clm: ${String(error)}`, { to: 'debug' }))
    return yield* next(e)
  })

  on('turn.complete', async ($, e, next) => {
    const out = await next(e)
    if (e.agentId === undefined) await afterTurn($).catch(error => $.ui.log(`clm: ${String(error)}`, { to: 'debug' }))
    return out
  })

  on('session.compact', async ($, e, next) => {
    if (e.agentId !== undefined || e.trigger === 'precompute') return next(e)
    let decided: Awaited<ReturnType<typeof decide>>
    try {
      decided = await decide($, e.trigger, e.instructions, e.messages, opts)
    } catch (error) {
      $.ui.log(`clm: compaction hook failed, native compaction runs instead (${String(error)})`, { to: 'debug' })
      return next(e)
    }
    if (decided) return decided
    const state = await load($)
    const out = await next(e)
    if (state.enabled && out.skip === undefined) {
      await save($, { ...state, revision: state.revision + 1, nonce: newNonce(), snapshot: undefined, isPending: false, lastTier: 0, lastOutcome: `native ${e.trigger} compaction replaced the conversation` })
    }
    return out
  })

  on('tool.call', { tool: `mcp__clm__${EDIT_TOOL}` }, async ($, e) => {
    const input = e as unknown as { action?: string; ops?: Op[] }
    try {
      return { result: await contextEdit($, input.action ?? 'apply', input.ops ?? []) }
    } catch (error) {
      return { result: `context_edit failed: ${String(error)}`, isError: true as const }
    }
  })

  on('tool.check', async ($, e, next) => {
    if (e.tool === `mcp__clm__${EDIT_TOOL}`) return { decision: 'allow' as const, reason: 'clm: edits only the live-context mirror' }
    if (!MIRROR_TOOLS.has(e.tool)) return next(e)
    const path = (e.input as { file_path?: unknown } | undefined)?.file_path
    const isMirror = typeof path === 'string' && (await mirrorOf($).catch(() => '')) === path
    return isMirror ? { decision: 'allow' as const, reason: 'clm: the live-context mirror' } : next(e)
  })

  on('command.run', { command: 'clm' }, async ($, e) => {
    const state = await load($)
    const arg = e.args.trim()
    if (arg === 'on' || arg === 'off') {
      await save($, { ...state, enabled: arg === 'on', snapshot: undefined, isPending: false })
      return { text: `clm ${arg}` }
    }
    return { text: await status($, state, opts) }
  })

  // `/clm-compact` becomes the compact prompt itself, so it runs as an ordinary turn
  // in every mode (a plugin's own submit waits for an idle REPL, which -p never has).
  on('prompt.submit', async ($, e, next) => {
    const match = /^\/clm-compact(?:\s+([\s\S]*))?$/.exec(e.text.trim())
    if (!match) return next(e)
    const state = await load($)
    if (!state.enabled) return next(e)
    const { tokens, window } = await contextTokens($)
    const budget = opts.budget > 0 ? opts.budget : window
    return next({ ...e, text: compactPrompt(await mirrorOf($), tokens, budget, match[1] ?? '') })
  })

  on('command.run', { command: 'clm-compact' }, async ($, e) => {
    const state = await load($)
    if (!state.enabled) return { text: 'clm is off; /clm on first' }
    const { tokens, window } = await contextTokens($)
    const budget = opts.budget > 0 ? opts.budget : window
    const text = compactPrompt(await mirrorOf($), tokens, budget, e.args)
    $.clock.after(0, () => void $.prompt.submit({ text, asUser: true }).catch(error => $.ui.log(`clm: ${String(error)}`)))
    return { text: 'Asked Claude to compact its live context.' }
  })
}

// The compaction CLM answers itself, or undefined to let the engine's run.
async function decide($: EngineInterface, trigger: string, instructions: string | undefined, messages: readonly SessionMessage[], opts: Options) {
  const state = await load($)
  if (!state.enabled) return undefined
  // A /compact after an edit not yet settled installs it, as the end of the turn would have.
  const settled = state.isPending ? state : await settle($, state)
  if (settled.isPending) return applyAndSave($, settled, messages)
  if (instructions === APPLY_TAG) return { skip: 'clm: no edit pending' }
  if (trigger === 'auto' && opts.guard) {
    const guarded = await guard($, state, messages, opts)
    if (guarded) {
      await save($, guarded.state)
      return { messages: guarded.messages }
    }
  }
  return undefined
}

async function applyAndSave($: EngineInterface, state: State, messages: readonly SessionMessage[]) {
  const out = await applyEdit($, state, messages)
  await save($, out.state)
  if (!out.messages) {
    await note($, `[LIVE CONTEXT] Your mirror edit was rejected (${out.state.lastOutcome}).`)
    return { skip: `clm: ${out.state.lastOutcome}` }
  }
  return { messages: out.messages, tokensBefore: out.tokensBefore, tokensAfter: out.tokensAfter }
}

files.hooks/document.ts:
// The mirror: render the conversation as an editable document, parse the model's
// edit, and turn it back into the message list a `session.compact` hook hands up.
// Pure functions only; ported from pi-clm's context-document.ts (MIT, Emanuel Casco).

import type { SessionMessage } from 'claude-code'

export const DOCUMENT_VERSION = 1

// What is kept of a render to judge an edit: digests, not bodies, so the saved
// state stays small however long the conversation grows.
export type Block = {
  id: string
  role: string
  key: string
  digest: string
}

export type Snapshot = {
  revision: number
  nonce: string
  blocks: Block[]
  textDigest: string
  firstUser?: { id: string; role: string; body: string }
}

export type ParsedBlock = { id: string; role: string; body: string }

export type Parsed =
  | { ok: true; blocks: ParsedBlock[]; isWholeRewrite: boolean }
  | { ok: false; reason: string }

export type BuiltMessage = {
  role: 'user' | 'assistant'
  text: string
  toolUses: SessionMessage['toolUses']
  handle?: string
}

export type Applied = {
  messages: BuiltMessage[]
  kept: number
  edited: number
  added: number
  removed: number
  suffix: number
  repaired: number
  charsBefore: number
  charsAfter: number
}

// FNV-1a, two lanes: a stable 16-hex digest without Node's crypto.
export function digest(text: string): string {
  let a = 0x811c9dc5
  let b = 0x01000193 ^ 0x9e3779b9
  for (let i = 0; i < text.length; i++) {
    const c = text.charCodeAt(i)
    a = Math.imul(a ^ c, 0x01000193)
    b = Math.imul(b ^ c ^ (i & 0xff), 0x01000193)
  }
  return (a >>> 0).toString(16).padStart(8, '0') + (b >>> 0).toString(16).padStart(8, '0')
}

// What identifies a message across `$.session.messages()` and a compaction's input.
// A tool use's answer is left out: it arrives later on the same message.
export function messageKey(m: SessionMessage): string {
  const uses = m.toolUses.map(u => u.tool_use_id).join(',')
  const results = (m.toolResults ?? []).map(r => `${r.tool_use_id}:${digest(r.text)}`).join(',')
  return digest(`${m.role}\u0001${m.text}\u0001${uses}\u0001${results}`)
}

export function roleOf(m: SessionMessage): string {
  if (m.role === 'assistant') return 'assistant'
  return m.toolResults?.length && !m.text.trim() ? 'tool' : 'user'
}

export function renderBody(m: SessionMessage): string {
  const parts: string[] = []
  if (m.text.trim()) parts.push(m.text.trim())
  for (const u of m.toolUses) parts.push(`[tool call: ${u.tool} id=${u.tool_use_id}]\n${JSON.stringify(u.input)}`)
  for (const r of m.toolResults ?? []) {
    parts.push(`[tool result id=${r.tool_use_id}${r.isError ? ' error' : ''}]\n${r.text}`)
  }
  return parts.join('\n\n')
}

const STRUCTURAL = /^(\\*)(\[\[(?:CTX_TURN|LIVE_CONTEXT) )/gm

export function escapeStructural(body: string): string {
  return body.replace(STRUCTURAL, (_m, s: string, start: string) => `\\${s}${start}`)
}

export function unescapeStructural(body: string): string {
  return body.replace(STRUCTURAL, (_m, s: string, start: string) => `${s.slice(1)}${start}`)
}

export function metaLine(revision: number, nonce: string): string {
  return `[[LIVE_CONTEXT version=${DOCUMENT_VERSION} revision=${revision} document=${nonce}]]`
}

export function headerLine(nonce: string, index: number, role: string, id: string): string {
  return `[[CTX_TURN document=${nonce} index=${index} role=${role} id=${id}]]`
}

export function render(messages: readonly SessionMessage[], revision: number, nonce: string): { snapshot: Snapshot; text: string } {
  const rendered = messages.map((m, i) => {
    const key = messageKey(m)
    return { id: `${i + 1}-${key.slice(0, 12)}`, role: roleOf(m), key, body: escapeStructural(renderBody(m)) }
  })
  const text = `${[
    metaLine(revision, nonce),
    '# Edit bodies, delete, reorder or add blocks (id=new-NAME). Keep this first line and the headers you retain.',
    ...rendered.map((b, i) => `${headerLine(nonce, i + 1, b.role, b.id)}\n${b.body}`),
  ].join('\n\n')}\n`
  const first = rendered.find(b => b.role === 'user')
  const snapshot: Snapshot = {
    revision,
    nonce,
    blocks: rendered.map(b => ({ id: b.id, role: b.role, key: b.key, digest: digest(b.body.trim()) })),
    textDigest: digest(text),
    firstUser: first && { id: first.id, role: first.role, body: first.body.trim() },
  }
  return { snapshot, text }
}

function escapeRegExp(value: string): string {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')
}

export function parse(text: string, snap: Snapshot): Parsed {
  const expected = metaLine(snap.revision, snap.nonce)
  const firstLine = text.split(/\r?\n/, 1)[0]?.trim() ?? ''
  if (firstLine !== expected) {
    return { ok: false, reason: `the first line must stay exactly: ${expected}` }
  }
  const headerRe = new RegExp(
    `^\\[\\[CTX_TURN document=${escapeRegExp(snap.nonce)} index=\\d+ role=([A-Za-z][A-Za-z0-9_-]*) id=([A-Za-z0-9-]+)\\]\\][ \\t]*$`,
    'gm',
  )
  const matches = [...text.matchAll(headerRe)]
  const known = new Set(snap.blocks.map(b => b.id))
  const body = text.slice(text.indexOf('\n') + 1)

  if (matches.length === 0) {
    const notes = stripHint(body).trim()
    if (!notes) return { ok: false, reason: 'the mirror is empty; nothing would remain' }
    const blocks: ParsedBlock[] = snap.firstUser ? [{ ...snap.firstUser }] : []
    blocks.push({ id: 'new-notes', role: 'notes', body: notes })
    return { ok: true, blocks, isWholeRewrite: true }
  }

  const seen = new Set<string>()
  const blocks: ParsedBlock[] = []
  const heads = matches.map(m => ({ at: m.index ?? 0, line: m[0], role: m[1] ?? '', id: m[2] ?? '' }))
  const preamble = stripHint(text.slice(firstLine.length, heads[0]?.at ?? text.length)).trim()
  if (preamble) blocks.push({ id: 'new-preamble', role: 'notes', body: preamble })
  for (const [i, h] of heads.entries()) {
    if (!h.id.startsWith('new-') && !known.has(h.id)) {
      return { ok: false, reason: `unknown block id ${h.id}: ids come only from current headers, or start with new-` }
    }
    if (seen.has(h.id)) return { ok: false, reason: `duplicate block id ${h.id}` }
    seen.add(h.id)
    const end = heads[i + 1]?.at ?? text.length
    blocks.push({ id: h.id, role: h.role, body: text.slice(h.at + h.line.length, end).trim() })
  }
  const stray = text
    .split(/\r?\n/)
    .map(l => l.trim())
    .filter(l => l.startsWith(`[[CTX_TURN document=${snap.nonce} `) && !heads.some(h => h.line.trim() === l))
  if (stray[0] !== undefined) return { ok: false, reason: `malformed header: ${stray[0].slice(0, 160)}` }
  return { ok: true, blocks, isWholeRewrite: false }
}

function stripHint(text: string): string {
  return text.replace(/^# Edit bodies, delete, reorder or add blocks.*$/m, '')
}

function textMessage(role: string, body: string): BuiltMessage {
  const text = unescapeStructural(body).trim()
  if (role === 'user') return { role: 'user', text, toolUses: [] }
  if (role === 'assistant') return { role: 'assistant', text, toolUses: [] }
  // Authored and tool roles reach the model as user-role text, never as authority.
  return { role: 'user', text: `[${role}]\n${text}`, toolUses: [] }
}

// Build the conversation the compaction installs: untouched blocks keep the
// engine's own message (by handle), edited and new blocks become text, messages
// that arrived after the snapshot follow unchanged, and broken tool pairs are
// flattened to text so the request stays legal.
// `isEditing` names the tool calls that performed the edit (the mirror's own
// traffic): they are dropped from what follows the snapshot, so the edit does not
// leave its working behind in the context it produced.
export function apply(
  parsed: ParsedBlock[],
  snap: Snapshot,
  current: readonly SessionMessage[],
  isEditing: (use: SessionMessage['toolUses'][number]) => boolean = () => false,
): Applied {
  const byId = new Map(snap.blocks.map(b => [b.id, b]))
  const baseline = new Map<string, number>()
  for (const b of snap.blocks) baseline.set(b.key, (baseline.get(b.key) ?? 0) + 1)

  const pool = new Map<string, SessionMessage[]>()
  const suffix: SessionMessage[] = []
  const left = new Map(baseline)
  for (const m of current) {
    const key = messageKey(m)
    const n = left.get(key) ?? 0
    if (n > 0) {
      left.set(key, n - 1)
      pool.set(key, [...(pool.get(key) ?? []), m])
    } else {
      suffix.push(m)
    }
  }

  type Item = { msg: BuiltMessage; source?: SessionMessage }
  const out: Item[] = []
  let kept = 0
  let edited = 0
  let added = 0
  const used = new Set<string>()
  for (const p of parsed) {
    const b = byId.get(p.id)
    if (b) used.add(b.id)
    if (b && p.role === b.role && digest(p.body) === b.digest) {
      const original = pool.get(b.key)?.shift()
      if (original) {
        out.push({ msg: { role: original.role, text: original.text, toolUses: original.toolUses, handle: original.handle }, source: original })
        kept++
      }
      continue
    }
    const built = textMessage(p.role, p.body)
    if (!built.text) continue
    out.push({ msg: built })
    if (b) edited++
    else added++
  }
  const editIds = new Set(suffix.flatMap(m => m.toolUses.filter(isEditing).map(u => u.tool_use_id)))
  for (const m of suffix) {
    const results = m.toolResults ?? []
    if (results.length > 0 && results.every(r => editIds.has(r.tool_use_id)) && !m.text.trim()) continue
    if (m.toolUses.length > 0 && m.toolUses.every(u => editIds.has(u.tool_use_id))) {
      if (m.text.trim()) out.push({ msg: { role: m.role, text: m.text, toolUses: [] } })
      continue
    }
    out.push({ msg: { role: m.role, text: m.text, toolUses: m.toolUses, handle: m.handle }, source: m })
  }

  const repaired = repairToolPairs(out)
  const messages = out.map(i => i.msg)
  if (messages[0]?.role !== 'user') messages.unshift({ role: 'user', text: '[context]', toolUses: [] })

  const charsBefore = current.reduce((n, m) => n + renderBody(m).length, 0)
  const charsAfter = messages.reduce((n, m) => n + m.text.length + JSON.stringify(m.toolUses.map(u => u.input)).length, 0)
  return {
    messages,
    kept,
    edited,
    added,
    removed: snap.blocks.filter(b => !used.has(b.id)).length,
    suffix: suffix.length,
    repaired,
    charsBefore,
    charsAfter,
  }
}

type RepairItem = { msg: BuiltMessage; source?: SessionMessage }

function flatten(item: RepairItem): void {
  if (!item.source) return
  const role = item.source.role === 'assistant' ? 'assistant' : roleOf(item.source)
  item.msg = textMessage(role, renderBody(item.source))
  item.source = undefined
}

function resultsOf(item: RepairItem | undefined): readonly { tool_use_id: string }[] {
  return item?.source?.toolResults ?? []
}

function repairToolPairs(items: RepairItem[]): number {
  let repaired = 0
  for (let i = 0; i < items.length; i++) {
    const it = items[i]
    const uses = it?.source?.role === 'assistant' ? it.source.toolUses : []
    if (!it || uses.length === 0) continue
    const want = new Set(uses.map(u => u.tool_use_id))
    const got = new Set<string>()
    let j = i + 1
    while (j < items.length && resultsOf(items[j]).length > 0 && got.size < want.size) {
      for (const r of resultsOf(items[j])) got.add(r.tool_use_id)
      j++
    }
    const isWhole = got.size === want.size && [...got].every(id => want.has(id))
    if (isWhole) {
      i = j - 1
      continue
    }
    flatten(it)
    for (const item of items.slice(i + 1, j)) flatten(item)
    repaired++
  }
  // A tool result whose call is no longer right before it.
  for (const [i, item] of items.entries()) {
    const results = resultsOf(item)
    if (results.length === 0) continue
    let k = i - 1
    while (k >= 0 && resultsOf(items[k]).length > 0) k--
    const call = items[k]?.source
    const ids = new Set(call?.role === 'assistant' ? call.toolUses.map(u => u.tool_use_id) : [])
    if (!results.every(r => ids.has(r.tool_use_id))) {
      flatten(item)
      repaired++
    }
  }
  return repaired
}

export function estimateTokens(chars: number): number {
  return Math.ceil(chars / 4)
}

export type Withheld = { id: string; tool: string; path: string; text: string }

// The overflow guard: replace the oldest large tool results with one-line notes
// (full text saved to a file) until the conversation fits `targetChars`. The
// newest results stay, so a re-read of a withheld file is never withheld again.
export function withhold(
  current: readonly SessionMessage[],
  targetChars: number,
  dir: string,
  minChars = 2000,
): { messages: BuiltMessage[]; withheld: Withheld[]; charsAfter: number } | undefined {
  const items: RepairItem[] = current.map(m => ({ msg: { role: m.role, text: m.text, toolUses: m.toolUses, handle: m.handle }, source: m }))
  const size = (m: SessionMessage) => renderBody(m).length
  let total = current.reduce((n, m) => n + size(m), 0)
  if (total <= targetChars) return undefined
  const toolOf = new Map<string, string>()
  for (const m of current) for (const u of m.toolUses) toolOf.set(u.tool_use_id, u.tool)
  const withheld: Withheld[] = []
  const lastResult = current.map(m => !!m.toolResults?.length).lastIndexOf(true)
  for (const [i, m] of current.entries()) {
    if (total <= targetChars) break
    if (!m.toolResults?.length || i === lastResult) continue
    const big = m.toolResults.filter(r => r.text.length >= minChars)
    if (big.length === 0) continue
    const lines: string[] = []
    for (const r of m.toolResults) {
      if (r.text.length < minChars) {
        lines.push(`[tool result id=${r.tool_use_id}]\n${r.text}`)
        continue
      }
      const tool = toolOf.get(r.tool_use_id) ?? 'tool'
      const path = `${dir}/withheld/${r.tool_use_id}.txt`
      withheld.push({ id: r.tool_use_id, tool, path, text: r.text })
      lines.push(
        `[CLM withheld] ${tool} result ${r.tool_use_id}: ~${estimateTokens(r.text.length)} tokens, full text at ${path}`,
      )
    }
    const note = lines.join('\n\n')
    total += note.length - size(m)
    items[i] = { msg: { role: 'user', text: `[tool]\n${note}`, toolUses: [] } }
  }
  if (withheld.length === 0 || total > targetChars) return undefined
  repairToolPairs(items)
  const messages = items.map(i => i.msg)
  return { messages, withheld, charsAfter: messages.reduce((n, m) => n + m.text.length, 0) }
}

export type Op =
  | { op: 'replace'; id: string; body: string }
  | { op: 'delete'; id: string }
  | { op: 'add'; id?: string; role?: string; body: string; after?: string }
  | { op: 'rewrite'; body: string }

export function serialize(blocks: readonly ParsedBlock[], snap: Snapshot): string {
  return `${[
    metaLine(snap.revision, snap.nonce),
    '# Edit bodies, delete, reorder or add blocks (id=new-NAME). Keep this first line and the headers you retain.',
    ...blocks.map((b, i) => `${headerLine(snap.nonce, i + 1, b.role, b.id)}\n${b.body}`),
  ].join('\n\n')}\n`
}

// The context_edit tool: apply operations to the mirror's current text and
// return the new text, or why not. Bodies given here are escaped, so a header
// typed into one stays text.
export function applyOps(text: string, snap: Snapshot, ops: readonly Op[]): { ok: true; text: string } | { ok: false; reason: string } {
  const parsed = parse(text, snap)
  if (!parsed.ok) return parsed
  let blocks = [...parsed.blocks]
  const find = (id: string) => blocks.findIndex(b => b.id === id)
  for (const [n, o] of ops.entries()) {
    const at = `operation ${n + 1} (${o.op})`
    if (o.op === 'rewrite') {
      if (!o.body.trim()) return { ok: false, reason: `${at}: empty body` }
      blocks = [...(snap.firstUser ? [{ ...snap.firstUser }] : []), { id: 'new-notes', role: 'notes', body: escapeStructural(o.body.trim()) }]
      continue
    }
    if (o.op === 'add') {
      const id = o.id ?? `new-${n + 1}-${digest(o.body).slice(0, 6)}`
      if (!/^new-[A-Za-z0-9-]+$/.test(id)) return { ok: false, reason: `${at}: an added block's id must look like new-NAME` }
      if (find(id) >= 0) return { ok: false, reason: `${at}: id ${id} already exists` }
      const role = o.role ?? 'notes'
      if (!/^[A-Za-z][A-Za-z0-9_-]*$/.test(role)) return { ok: false, reason: `${at}: bad role ${role}` }
      const block = { id, role, body: escapeStructural(o.body.trim()) }
      if (o.after === undefined) blocks.push(block)
      else if (o.after === 'start') blocks.unshift(block)
      else {
        const i = find(o.after)
        if (i < 0) return { ok: false, reason: `${at}: no block ${o.after}` }
        blocks.splice(i + 1, 0, block)
      }
      continue
    }
    const i = find(o.id)
    if (i < 0) return { ok: false, reason: `${at}: no block ${o.id} (list the blocks for current ids)` }
    if (o.op === 'delete') blocks.splice(i, 1)
    else blocks[i] = { ...blocks[i]!, body: escapeStructural(o.body.trim()) }
  }
  return { ok: true, text: serialize(blocks, snap) }
}

export function listBlocks(text: string, snap: Snapshot): string {
  const parsed = parse(text, snap)
  if (!parsed.ok) return `The mirror does not parse: ${parsed.reason}`
  const lines = parsed.blocks.map(b => {
    const preview = unescapeStructural(b.body).replace(/\s+/g, ' ').slice(0, 100)
    return `${b.id} ${b.role} ~${estimateTokens(b.body.length)} tok: ${preview}`
  })
  const total = estimateTokens(parsed.blocks.reduce((n, b) => n + b.body.length, 0))
  return [`${parsed.blocks.length} blocks, ~${total} tokens`, ...lines].join('\n')
}

